// Generates src/shared/scene/scenes.generated.ts from assets/scenes/*.svg (the source of truth).
// Strips the content-credentials <metadata> block and its namespace; the app draws with SvgXml.
// Run: pnpm gen:scenes. `--check` fails if the generated file is stale (used by lint/CI).
import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../../../assets/scenes/', import.meta.url);
const out = new URL('../src/shared/scene/scenes.generated.ts', import.meta.url);
const clean = (svg) =>
  svg
    .replace(/<metadata>[\s\S]*?<\/metadata>/g, '')
    .replace(/\s+xmlns:c2pa="[^"]*"/g, '')
    .replace(/>\s+</g, '><')
    .trim();

const scenes = { SCENE_DAY: 'scene-day.svg', SCENE_NIGHT: 'scene-lab-night.svg' };
const body = Object.entries(scenes)
  .map(
    ([name, file]) =>
      `export const ${name} = ${JSON.stringify(clean(readFileSync(new URL(file, root), 'utf8')))};`,
  )
  .join('\n\n');
const ts = `// GENERATED by scripts/gen-scenes.mjs from assets/scenes. Do not edit by hand.\n\n${body}\n`;

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(out, 'utf8');
  } catch {}
  if (current !== ts) {
    console.error('scenes.generated.ts is out of date. Run: pnpm --filter mobile gen:scenes');
    process.exit(1);
  }
} else {
  writeFileSync(out, ts);
  console.log('Wrote src/shared/scene/scenes.generated.ts');
}
